CREATE TABLE game_builds(id BINARY(16) PRIMARY KEY,version_id BINARY(16) NOT NULL,uploaded_by BINARY(16) NOT NULL,metadata_json TEXT NOT NULL,status VARCHAR(30) NOT NULL,artifact_key VARCHAR(512),checksum_sha256 VARCHAR(64),file_size BIGINT NOT NULL,content_type VARCHAR(255),created_at TIMESTAMP(6) NOT NULL,revision BIGINT NOT NULL,INDEX idx_build_version(version_id));
CREATE TABLE build_logs(id BINARY(16) PRIMARY KEY,build_id BINARY(16) NOT NULL,level VARCHAR(20) NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL,INDEX idx_build_log(build_id,created_at),FOREIGN KEY(build_id) REFERENCES game_builds(id) ON DELETE CASCADE);